/*
 * A373624  Number of distinct subsets of Z/nZ generated by powers.
 * https://oeis.org/A373624
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 76, u16 n <= 76, u32 n <= 76, u64 n <= 76, u128 n <= 76,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Sequence A373624: Number of distinct subsets of Z/nZ generated by powers.
 * Implementation: for each p in Z/nZ generate the orbit of 1 under
 * multiplication by p modulo n, store it as a bitset, and count
 * distinct bitsets.  Complexity O(n^2) in the worst case, acceptable for
 * n ≤ 10000.
 *
 * The function is self‑contained and uses only the allowed headers and
 * conventions.  All dynamic memory is freed before returning.
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* External type definitions provided by the build system */
seq_t a(idx_t n)
{
    /* a(0) is defined as 0 */
    if (n == 0ULL) {
        return 0;
    }

    /* Number of 64‑bit words needed to represent n bits. */
    const size_t bitlen = (size_t)((n + 63ULL) >> 6);

    /* Visitation array: 16‑bit counter per element to avoid clearing each time. */
    uint16_t *vis = (uint16_t *)calloc((size_t)n, sizeof(uint16_t));
    if (!vis) return 0;                  /* Out of memory: fall back to zero. */

    uint16_t counter = 1;                 /* Current visitation stamp. */

    /* Hash table for unique subsets.
     * We store a 64‑bit hash and a pointer to the bitset.
     * Table size is the next power of two ≥ 2·n for a load factor < 0.5.
     */
    size_t table_size = 1;
    while (table_size < 2ULL * n) table_size <<= 1;
    struct Entry { uint64_t hash; uint64_t *bits; } *table =
        (struct Entry *)calloc(table_size, sizeof(struct Entry));
    if (!table) { free(vis); return 0; }

    seq_t unique_cnt = 0;                 /* Result to be returned. */

    /* Loop over all p in Z/nZ */
    for (idx_t p = 0ULL; p < n; ++p) {
        /* Increment visitation stamp, wrap if needed */
        ++counter;
        if (counter == 0) {
            memset(vis, 0, (size_t)n * sizeof(uint16_t));
            counter = 1;
        }

        /* Allocate fresh bitset for this p */
        uint64_t *bits = (uint64_t *)calloc(bitlen, sizeof(uint64_t));
        if (!bits) break;                /* Memory error: terminate early. */

        /* Generate the orbit starting from 1 */
        idx_t cur = (idx_t)(1ULL % n);
        while (vis[cur] != counter) {
            vis[cur] = counter;
            bits[cur >> 6] |= ((uint64_t)1U << (cur & 63ULL));
            cur = (idx_t)((cur * p) % n);
        }

        /* Compute a 64‑bit hash for the bitset */
        uint64_t h = 0ULL;
        for (size_t i = 0; i < bitlen; ++i) {
            h = h * 1315423911ULL ^ bits[i];
        }

        /* Linear probing for insertion/lookup */
        size_t idx = h & (table_size - 1);
        while (true) {
            if (!table[idx].bits) {
                /* Empty slot: insert new subset */
                table[idx].bits = bits;
                table[idx].hash = h;
                ++unique_cnt;
                break;
            }
            if (table[idx].hash == h) {
                /* Possible match: compare words */
                bool eq = true;
                for (size_t i = 0; i < bitlen; ++i) {
                    if (table[idx].bits[i] != bits[i]) {
                        eq = false;
                        break;
                    }
                }
                if (eq) {
                    /* Duplicate subset found */
                    free(bits);
                    break;
                }
            }
            idx = (idx + 1) & (table_size - 1);   /* Wrap around */
        }
    }

    /* Clean up all allocated bitsets */
    for (size_t i = 0; i < table_size; ++i) {
        if (table[i].bits) free(table[i].bits);
    }
    free(table);
    free(vis);

    return unique_cnt;
}
